function result = senloraSymmetricV8Decode(observation,common,config,plan)
%SENLORASYMMETRICV8DECODE Frozen single-entry Joint-block V8 receiver.

if ~isfield(plan,'parametersFrozen') || ~plan.parametersFrozen
    error('EXP5V8:FrozenPlan','The promoted V8 requires the frozen plan.');
end
result = senloraSymmetricV8JointBlockDecode( ...
    observation,common,config,plan);

c = config.parent;
result.methodName = 'SenLoRa-Symmetric-V8-Frozen-Joint-Block';
result.methodId = 'senlora-symmetric-native-v8';
result.algorithmVersion = plan.receiverVersion;
appliedBlocks = logical(result.blockAccepted(:));
appliedBlocks(end) = false;
result.virtualPilotAccepted = repelem( ...
    appliedBlocks,c.hammingCodewordLength);
result.explicitMidambleAccepted = false(0,1);
result.monitor = struct( ...
    'symbolIndex',(1:c.payloadSymbolCount).', ...
    'appliedCompensationBins',result.estimatedCfoBins(:), ...
    'acceptedMeasurement',result.virtualPilotAccepted, ...
    'rateGain',repmat(result.rateGain,c.payloadSymbolCount,1));
result.decision = struct( ...
    'selectedBranchName','joint-block-cfo-hamming-ml', ...
    'predictedFrameDriftBins',abs( ...
        result.jointPreambleEstimate.rateBinsPerSec)*plan.frameDurationSec, ...
    'rateGain',result.rateGain, ...
    'preambleRateBinsPerSec', ...
        result.jointPreambleEstimate.rateBinsPerSec, ...
    'appliedInitialRateBinsPerSec',result.bootstrap.rateBinsPerSec, ...
    'staticCfoAtPayloadBins',result.bootstrap.staticCfoAtPayloadBins, ...
    'dynamicCfoAtPayloadBins',result.bootstrap.dynamicCfoAtPayloadBins, ...
    'candidateVirtualPilots',c.payloadSymbolCount, ...
    'acceptedVirtualPilots',sum(result.virtualPilotAccepted), ...
    'acceptedBlocks',sum(result.blockAccepted), ...
    'maximumResidualBins',max(abs(result.selectedResidualBins)), ...
    'passCount',2,'sameEntryAcrossCases',true, ...
    'parametersFrozen',true,'usesExplicitMidambles',false, ...
    'usesOrbitTruth',false,'usesTargetSer',false);
result.sameEntryAcrossCases = true;
result.parametersFrozen = true;
end
